/**
 * Pricing Methods Population Script
 *
 * The description of each engine that a pair names. ORE calls a pricing method an
 * engine.
 *
 * Generated by projects/ores.seeder/datasets/ore_pricing_engines/generate_vocabulary_sql.py
 * from the ORE user guide. Do not edit it by hand: change the generator and run it again.
 * This script is idempotent.
 */

\echo '--- Pricing Methods ---'

insert into ores_analytics_pricing_methods_tbl (
    code, tenant_id, version, description, detail, source, modified_by, change_reason_code, change_commentary
) values
    ('AMC', ores_utility_system_tenant_id_fn(), 0, 'American Monte Carlo engine for use inside an exposure simulation.', 'Builds an engine that prices the product on the paths of the exposure simulation with a regression, so the product is valued once for all dates. See the ORE AMC documentation.', 'ore_guide', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('AMCCG', ores_utility_system_tenant_id_fn(), 0, 'American Monte Carlo engine on the computation graph.', 'The AMC engine for the computation graph. It supports automatic differentiation for sensitivities. See the ORE AMC documentation.', 'ore_guide', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('AccrualRepoEngine', ores_utility_system_tenant_id_fn(), 0, 'Values a bond repo by accrual.', 'Builds an AccrualBondRepoEngine. The engine accrues the repo cash at the repo rate.', 'ore_code', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('Analytic', ores_utility_system_tenant_id_fn(), 0, 'Closed-form pricing engine of the product.', 'Prices the product with a closed formula of the model. The product decides which formula.', 'authored', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('AnalyticBarrierEngine', ores_utility_system_tenant_id_fn(), 0, 'Closed-form price of a single barrier option.', 'Prices a European barrier option with the formulas of Haug, Reiner and Rubinstein.', 'authored', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('AnalyticCashSettledEuropeanEngine', ores_utility_system_tenant_id_fn(), 0, 'Closed-form price of a cash-settled European option.', 'Prices a European option that settles in cash, so the payment follows the price at expiry and not the delivery of the underlying.', 'authored', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('AnalyticContinuousGeometricAPEngine', ores_utility_system_tenant_id_fn(), 0, 'Closed-form price of a continuous geometric average price Asian option.', 'The average is the geometric mean over a continuous window, which gives a closed formula.', 'authored', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('AnalyticDigitalAmericanEngine', ores_utility_system_tenant_id_fn(), 0, 'Closed-form price of a one-touch or no-touch digital option.', 'Builds an AnalyticDigitalAmericanEngine for a one touch, or an AnalyticDigitalAmericanKOEngine for a no touch.', 'ore_code', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('AnalyticDiscreteGeometricAPEngine', ores_utility_system_tenant_id_fn(), 0, 'Closed-form price of a discrete geometric average price Asian option.', 'The average is the geometric mean over fixing dates, which gives a closed formula.', 'authored', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('AnalyticDiscreteGeometricASEngine', ores_utility_system_tenant_id_fn(), 0, 'Closed-form price of a discrete geometric average strike Asian option.', 'The strike is the geometric mean over fixing dates, which gives a closed formula.', 'authored', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('AnalyticDoubleBarrierBinaryEngine', ores_utility_system_tenant_id_fn(), 0, 'Closed-form price of a double barrier binary option.', 'Prices a digital option that knocks in or out at an upper and a lower barrier.', 'authored', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('AnalyticDoubleBarrierEngine', ores_utility_system_tenant_id_fn(), 0, 'Closed-form price of a double barrier option.', 'Prices a vanilla option that knocks in or out at an upper and a lower barrier, with the Ikeda-Kunitomo series.', 'authored', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('AnalyticEuropeanEngine', ores_utility_system_tenant_id_fn(), 0, 'Closed-form Black-Scholes price of a European option.', 'Prices a European option with the Black-Scholes formula for the model of the pair.', 'authored', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('AnalyticEuropeanForwardEngine', ores_utility_system_tenant_id_fn(), 0, 'Closed-form price of an option on a forward.', 'Prices a European option on a forward or future with the Black formula. The underlying is the forward and not the spot.', 'authored', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('AnalyticalApproximation', ores_utility_system_tenant_id_fn(), 0, 'Analytical approximation for average price options.', 'Builds a CommodityAveragePriceOptionAnalyticalEngine. The setting Volatility selects the model for the average.', 'ore_code', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('BaroneAdesiWhaleyApproximationEngine', ores_utility_system_tenant_id_fn(), 0, 'Barone-Adesi and Whaley approximation for American options.', 'A quick analytic approximation of the early exercise premium of an American option.', 'authored', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('BlackAnalytic', ores_utility_system_tenant_id_fn(), 0, 'Black or Bachelier CPI coupon pricer.', 'Builds a BlackCPICouponPricer or a BachelierCPICouponPricer, depending on the volatility input.', 'ore_code', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('BlackAverageBMACouponPricer', ores_utility_system_tenant_id_fn(), 0, 'Coupon pricer for capped and floored average BMA coupons.', 'Prices the cap and floor of an average BMA indexed coupon with Black or Bachelier.', 'ore_code', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('BlackAverageONIndexedCouponPricer', ores_utility_system_tenant_id_fn(), 0, 'Coupon pricer for capped and floored average overnight coupons.', 'Prices the cap and floor of an average overnight indexed coupon with Black or Bachelier.', 'ore_code', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('BlackBachelierSwaptionEngine', ores_utility_system_tenant_id_fn(), 0, 'Black or Bachelier price of a European swaption.', 'Builds a BlackMultiLegOptionEngine. The volatility surface decides between Black and Bachelier.', 'ore_code', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('BlackBondOptionEngine', ores_utility_system_tenant_id_fn(), 0, 'Black price of a bond option.', 'Builds a BlackBondOptionEngine. The option is on the forward price of the bond.', 'ore_code', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('BlackCdsOptionEngine', ores_utility_system_tenant_id_fn(), 0, 'Black price of an option on a credit default swap.', 'Builds a BlackCdsOptionEngine. The option is on the forward spread of the default swap.', 'ore_code', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('BlackIborCouponPricer', ores_utility_system_tenant_id_fn(), 0, 'Coupon pricer for capped and floored Ibor coupons.', 'Prices the cap and floor of an Ibor coupon with Black or Bachelier.', 'ore_code', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('BlackIndexCdsOptionEngine', ores_utility_system_tenant_id_fn(), 0, 'Black price of an option on an index credit default swap.', 'Builds a BlackIndexCdsOptionEngine. The option is on the forward spread of the index.', 'ore_code', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('BlackInterpolatedIborCouponPricer', ores_utility_system_tenant_id_fn(), 0, 'Coupon pricer for capped and floored interpolated Ibor coupons.', 'Prices the cap and floor of a coupon that interpolates two Ibor tenors, with Black or Bachelier.', 'ore_code', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('BlackOvernightIndexedCouponPricer', ores_utility_system_tenant_id_fn(), 0, 'Coupon pricer for capped and floored overnight coupons.', 'Prices the cap and floor of an overnight indexed coupon with Black or Bachelier.', 'ore_code', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('BlackQuantoEquityCouponPricer', ores_utility_system_tenant_id_fn(), 0, 'Equity coupon pricer with a quanto adjustment.', 'Prices an equity coupon in another currency. The setting ApplyConvexityAdjustment switches the convexity adjustment.', 'ore_guide', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('Bucketing', ores_utility_system_tenant_id_fn(), 0, 'Hull-White bucketing of the loss distribution of a tranche.', 'Builds an IndexCdsTrancheEngine. The loss distribution comes from the bucketing method of Hull and White.', 'ore_code', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('CallSpreadCouponPricer', ores_utility_system_tenant_id_fn(), 0, 'Range accrual pricer by call spread replication.', 'Builds a RangeAccrualPricerByCallSpread. The pricer reads the optionlet surface directly and prices each daily observation as a call spread on caplets.', 'ore_guide', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('CallSpreadEngine', ores_utility_system_tenant_id_fn(), 0, 'Digital option price by call spread replication.', 'Prices a digital option as the spread of two vanilla options around the strike, so the volatility smile enters the price.', 'ore_guide', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('CapFlooredNonStdYYCouponPricer', ores_utility_system_tenant_id_fn(), 0, 'Coupon pricer for non-standard year-on-year inflation coupons.', 'Builds a non-standard Black, unit displaced Black or Bachelier year-on-year coupon pricer, depending on the volatility input.', 'ore_code', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('CapFlooredYYCouponPricer', ores_utility_system_tenant_id_fn(), 0, 'Coupon pricer for year-on-year inflation coupons.', 'Builds a Black, unit displaced Black or Bachelier year-on-year coupon pricer, depending on the volatility input.', 'ore_code', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('CommodityCalendarSpreadOptionBachelierEngine', ores_utility_system_tenant_id_fn(), 0, 'Bachelier price of a commodity calendar spread option.', 'Prices an option on the difference of two forward prices of one commodity at two delivery dates.', 'authored', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('CommoditySpreadOptionEngine', ores_utility_system_tenant_id_fn(), 0, 'Analytic price of a commodity spread option.', 'Builds a CommoditySpreadOptionAnalyticalEngine. It uses the Bachelier model or the Kirk approximation of Clark, Commodity Option Pricing, section 2.9. The correlation of the two commodities comes from the market.', 'ore_guide', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('CommoditySwapEngine', ores_utility_system_tenant_id_fn(), 0, 'Discounting price of a commodity swap.', 'Builds a DiscountingSwapEngine for the legs of a commodity swap.', 'ore_code', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('CpiCapEngine', ores_utility_system_tenant_id_fn(), 0, 'Black or Bachelier price of a CPI cap or floor.', 'Builds a CPIBlackCapFloorEngine or a CPIBachelierCapFloorEngine, depending on the volatility type of the market surface.', 'ore_code', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('DiscountingBondFutureEngine', ores_utility_system_tenant_id_fn(), 0, 'Discounting price of a bond future.', 'Builds a DiscountingBondFutureEngine for the future on the cheapest to deliver bond.', 'ore_code', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('DiscountingBondTRSEngine', ores_utility_system_tenant_id_fn(), 0, 'Discounting price of a bond total return swap.', 'Builds a DiscountingBondTRSEngine. The bond leg and the funding leg are discounted.', 'ore_code', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('DiscountingCommodityForwardEngine', ores_utility_system_tenant_id_fn(), 0, 'Discounting price of a commodity forward.', 'Builds a DiscountingCommodityForwardEngine.', 'ore_code', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('DiscountingCreditLinkedSwapEngine', ores_utility_system_tenant_id_fn(), 0, 'Discounting price of a credit linked swap.', 'Builds a DiscountingCreditLinkedSwapEngine.', 'ore_code', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('DiscountingCrossCurrencySwapEngine', ores_utility_system_tenant_id_fn(), 0, 'Discounting price of a cross currency swap.', 'Builds the discounting currency swap engine. Each leg is discounted in its own currency and converted at the spot rate.', 'ore_code', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('DiscountingEquityForwardEngine', ores_utility_system_tenant_id_fn(), 0, 'Discounting price of an equity forward.', 'Builds a DiscountingEquityForwardEngine.', 'ore_code', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('DiscountingForwardBondEngine', ores_utility_system_tenant_id_fn(), 0, 'Discounting price of a forward bond.', 'Builds a DiscountingForwardBondEngine.', 'ore_code', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('DiscountingFxForwardEngine', ores_utility_system_tenant_id_fn(), 0, 'Discounting price of an FX forward.', 'Builds a DiscountingFxForwardEngine. Each currency leg is discounted and converted at the spot rate.', 'ore_code', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('DiscountingRepoEngine', ores_utility_system_tenant_id_fn(), 0, 'Discounting price of a bond repo.', 'Builds a DiscountingBondRepoEngine.', 'ore_code', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('DiscountingRiskyBondEngine', ores_utility_system_tenant_id_fn(), 0, 'Discounting price of a bond with credit risk.', 'Builds a DiscountingRiskyBondEngine. It discounts the coupons with the survival probability of the issuer and adds the recovery on default.', 'ore_code', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('DiscountingRiskyBondEngineMultiState', ores_utility_system_tenant_id_fn(), 0, 'Risky bond engine for the ORE credit model.', 'Builds a DiscountingRiskyBondEngineMultiState for use in the credit model. See the ORE credit model documentation.', 'ore_guide', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('DiscountingSwapEngine', ores_utility_system_tenant_id_fn(), 0, 'Discounting price of a swap.', 'Builds a DiscountingSwapEngine. Each leg is projected on its curve and discounted.', 'ore_code', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('EquityCouponPricer', ores_utility_system_tenant_id_fn(), 0, 'Pricer for an equity leg coupon.', 'Takes no setting. It prices the coupons of an equity leg from the equity forward.', 'ore_guide', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('EquityVarianceSwap', ores_utility_system_tenant_id_fn(), 0, 'Replicating price of a variance or volatility swap.', 'Builds a GeneralisedReplicatingVarianceSwapEngine or a VolatilityFromVarianceSwapEngine, depending on the moment type.', 'ore_code', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('FD', ores_utility_system_tenant_id_fn(), 0, 'Finite difference engine.', 'Solves the pricing equation of the model on a grid of state and time. The settings set the grid size, the scheme and the time steps.', 'ore_guide', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('FdBlackScholesBarrierEngine', ores_utility_system_tenant_id_fn(), 0, 'Finite difference price of a barrier option.', 'Builds a FdBlackScholesBarrierEngine. It handles barriers that have no closed formula.', 'ore_code', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('FdBlackScholesVanillaEngine', ores_utility_system_tenant_id_fn(), 0, 'Finite difference price of an American vanilla option.', 'Builds a FdBlackScholesVanillaEngine. The grid handles early exercise.', 'ore_code', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('FloatingRateCouponPricer', ores_utility_system_tenant_id_fn(), 0, 'Range accrual coupon pricer on a swaption smile.', 'Builds a RangeAccrualPricerByBgm for each coupon of the range accrual leg.', 'ore_guide', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('Grid', ores_utility_system_tenant_id_fn(), 0, 'Convolution grid engine for the LGM model.', 'Rolls the value back on a grid of the LGM state with numerical integration, after Hagan, Methodology for callable swaps and Bermudan exercise into swaptions. The settings set the width and the point count of the grid.', 'ore_guide', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('IborCapEngine', ores_utility_system_tenant_id_fn(), 0, 'Black or Bachelier price of a cap or floor.', 'Builds a BlackCapFloorEngine or a BachelierCapFloorEngine, depending on the volatility type.', 'ore_code', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('Intrinsic', ores_utility_system_tenant_id_fn(), 0, 'Intrinsic value of the product.', 'Builds an IntrinsicAscotEngine. The value is the payoff at the current market with no time value.', 'ore_code', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('LinearTSRPricer', ores_utility_system_tenant_id_fn(), 0, 'Linear terminal swap rate pricer for CMS coupons.', 'Builds a LinearTSRPricer. The settings choose the replication policy and the rate bounds.', 'ore_code', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('MC', ores_utility_system_tenant_id_fn(), 0, 'Monte Carlo engine.', 'Prices by simulation of the model with the Longstaff-Schwartz regression for early exercise. The settings choose the sequence, the seed, the number of samples and the regression basis.', 'ore_guide', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('MCCG', ores_utility_system_tenant_id_fn(), 0, 'Monte Carlo engine on the computation graph.', 'Builds a MacCgMultiLegOptionEngine. It supports automatic differentiation for first-order sensitivities.', 'ore_guide', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('MCDiscreteArithmeticAPEngine', ores_utility_system_tenant_id_fn(), 0, 'Monte Carlo price of an arithmetic average price Asian option.', 'Builds a MCDiscreteArithmeticAPEngine with Sobol sequences.', 'ore_code', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('MCDiscreteArithmeticASEngine', ores_utility_system_tenant_id_fn(), 0, 'Monte Carlo price of an arithmetic average strike Asian option.', 'Builds a MCDiscreteArithmeticASEngine with Sobol sequences.', 'ore_code', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('MCDiscreteGeometricAPEngine', ores_utility_system_tenant_id_fn(), 0, 'Monte Carlo price of a geometric average price Asian option.', 'Builds a MCDiscreteGeometricAPEngine with Sobol sequences.', 'ore_code', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('MCScript', ores_utility_system_tenant_id_fn(), 0, 'Monte Carlo engine that runs a script.', 'Builds a CliquetOptionMcScriptEngine, which uses the scripted trade framework.', 'ore_code', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('MidPointCdsEngine', ores_utility_system_tenant_id_fn(), 0, 'Mid-point price of a credit default swap.', 'Builds a MidPointCdsEngine. The default time in each period is the mid point of the period.', 'ore_code', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('MidPointCdsEngineMultiState', ores_utility_system_tenant_id_fn(), 0, 'Credit default swap engine for the ORE credit model.', 'Builds a MidPointCdsEngineMultiState. Only the credit model uses it. See the ORE credit model documentation.', 'ore_guide', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('MidPointIndexCdsEngine', ores_utility_system_tenant_id_fn(), 0, 'Mid-point price of an index credit default swap.', 'Builds a MidPointIndexCdsEngine.', 'ore_code', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('MonteCarlo', ores_utility_system_tenant_id_fn(), 0, 'Monte Carlo engine.', 'Prices by simulation of the underlying. The settings choose the number of samples, the seed and the variance reduction.', 'authored', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('MonteCarloCBOEngine', ores_utility_system_tenant_id_fn(), 0, 'Monte Carlo price of a collateralised bond obligation.', 'Builds a MonteCarloCBOEngine. It simulates the defaults of the pool and the waterfall of the tranches.', 'ore_code', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('Numerical', ores_utility_system_tenant_id_fn(), 0, 'Numerical integration pricer for CMS coupons.', 'Builds a NumericHaganPricer. It integrates the replication integral numerically.', 'ore_code', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('NumericalIntegrationEngine', ores_utility_system_tenant_id_fn(), 0, 'Numerical integration price of an index CDS option.', 'Builds a NumericalIntegrationIndexCdsOptionEngine.', 'ore_code', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('ScriptedTrade', ores_utility_system_tenant_id_fn(), 0, 'Scripted trade pricing engine.', 'Builds a ScriptedInstrumentPricingEngine, or a variant. See the ORE scripted trade documentation.', 'ore_guide', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('TurnbullWakemanAsianEngine', ores_utility_system_tenant_id_fn(), 0, 'Turnbull-Wakeman approximation for arithmetic Asian options.', 'Prices an arithmetic average option by matching the first two moments of the average to a lognormal variable.', 'authored', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('YYCapEngine', ores_utility_system_tenant_id_fn(), 0, 'Black or Bachelier price of a year-on-year inflation cap or floor.', 'Builds a Black, unit displaced Black or Bachelier year-on-year cap floor engine, depending on the volatility type of the market surface.', 'ore_code', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary')
on conflict (tenant_id, code)
where valid_to = ores_utility_infinity_timestamp_fn()
do nothing;

select 'Pricing Methods' as entity, count(*) as count
from ores_analytics_pricing_methods_tbl
where valid_to = ores_utility_infinity_timestamp_fn();
